import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';
import { claimsKey } from '../claims/claims';
import { statementsKey, useStatements } from './statements';

function StatementsHead() {
  return (
    <>
      <th>Statements</th>
      <th>Stated total</th>
      <th>Stated on</th>
      <th />
    </>
  );
}

/** A person's statement count, their last statement's due-total and date, and the button that takes one: it
 *  records their due-total now and binds each of their claims that counts to its rate figure now (not floored); and
 *  the button that cancels their last statement (a steward only), making the claims it bound live again. */
function PersonStatements({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const statements = useStatements(sheetId);
  const queryClient = useQueryClient();
  const mine = statements.data?.find((s) => s.personId === person.id);
  const rowAction = usePersonRowAction(sheetId, person.id, 'statement');
  const take = useMutation({
    mutationFn: () =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/statements`, { by: user }),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]),
  });

  const cancelAction = usePersonRowAction(sheetId, person.id, 'unstate');
  const cancel = useMutation({
    mutationFn: () =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/statements/cancel`, { by: user }),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]),
  });

  return (
    <>
      <td data-testid="person-statement-count">{mine?.count ?? 0}</td>
      <td data-testid="person-stated-total">{mine?.dueTotal ?? ''}</td>
      <td data-testid="person-statement-date">{mine?.date ?? ''}</td>
      <td>
        <button
          type="button"
          data-testid="person-statement"
          disabled={take.isPending}
          onClick={() => {
            rowAction.take();
            take.reset();
            take.mutate();
          }}
        >
          Statement
        </button>
        {take.isError && rowAction.isLatest && <span data-testid="person-error"> Could not take a statement for this person.</span>}
        <button
          type="button"
          data-testid="person-unstate"
          disabled={cancel.isPending}
          onClick={() => {
            cancelAction.take();
            cancel.reset();
            cancel.mutate();
          }}
        >
          Cancel statement
        </button>
        {cancel.isError && cancelAction.isLatest && <span data-testid="person-error"> Could not cancel this person's statement.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 30, Component: StatementsHead }),
  PersonRow.fill({ order: 30, Component: PersonStatements }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { peopleKey, type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';

function HoldHead() {
  return (
    <>
      <th>On hold</th>
      <th />
    </>
  );
}

/** Whether the person has any hold, their holds (one line each), and the dates and button that add one: from the
 *  from-date (blank: the sheet's today) until the to-date (blank: open-ended). Only their OPEN or PENDING claims dated
 *  within a hold, and not bound by a statement, count in no live total. A refused hold shows the row's error. */
function PersonHold({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'hold');
  const hold = useMutation({
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/hold`, { ...dates, by: user }),
    onSuccess: () => {
      setFrom('');
      setTo('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        {(person.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? ''}
          </div>
        ))}
        <input
          data-testid="person-hold-from"
          placeholder="from yyyy-MM-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          data-testid="person-hold-to"
          placeholder="to yyyy-MM-dd"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            hold.reset();
            hold.mutate({ from: from.trim(), to: to.trim() });
          }}
        >
          Hold
        </button>
        {hold.isError && rowAction.isLatest && <span data-testid="person-error"> Could not hold this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 50, Component: HoldHead }),
  PersonRow.fill({ order: 50, Component: PersonHold }),
];

