package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored sheets. A sheet never changed has no row and reads as starting on the real date. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        return new Sheet(id, today(id), archived(id));
    }

    /**
     * The sheet's today. Use this — never {@code LocalDate.now()} — for every decision or default
     * that depends on the date.
     */
    public LocalDate today(String id) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    /** Whether a steward archived the sheet: an archived sheet refuses every change. */
    public boolean archived(String id) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_archived WHERE sheet_id = ?", Integer.class, id);
        return found != null && found > 0;
    }

    /** Archives the sheet; false when it was already archived. */
    public boolean archive(String id, String by) {
        if (archived(id)) {
            return false;
        }
        jdbc.update("INSERT INTO sheet_archived (sheet_id, archived_by) VALUES (?, ?)", id, by);
        return true;
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", id, today);
    }
}
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored status logs of the claims, kept per sheet, each claim's lines oldest first. */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;

    public ClaimLogRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void add(String sheetId, ClaimLogLine line) {
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, line.claimId(), line.status().name(), line.by(), Date.valueOf(line.date()), line.due());
    }

    /** The claim's lines, oldest first. */
    public List<ClaimLogLine> of(String sheetId, long claimId) {
        return jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                ClaimLogRepository::map, sheetId, claimId);
    }

    /** Every claim's lines on the sheet, by claim id, each oldest first. */
    public Map<Long, List<ClaimLogLine>> bySheet(String sheetId) {
        return jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
                ClaimLogRepository::map, sheetId).stream()
                .collect(Collectors.groupingBy(ClaimLogLine::claimId, LinkedHashMap::new, Collectors.toList()));
    }

    private static ClaimLogLine map(ResultSet rs, int n) throws SQLException {
        return new ClaimLogLine(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getString("by_user"), rs.getObject("log_date", LocalDate.class), rs.getString("due"));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** One line of a claim's status log: the status it took, who made the change, the sheet's today when it was made, and
 *  the claim's due as shown at that moment (two decimals, or n/a). */
public record ClaimLogLine(long claimId, ClaimStatus status, String by, LocalDate date, String due) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id; one not on the sheet is a 404. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository people, Out<Person> person) throws PersonNotFoundException {
        Person found;
        try {
            found = people.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new PersonNotFoundException("No person " + personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

/** A person's values that cannot be kept: an empty name, or a grade other than A, B or C. */
public class InvalidPersonException extends Exception {
    public InvalidPersonException(String message) {
        super(message);
    }
}

