-- A period can be soft-closed: its due-total (closed_total) and each person's (period_person_total) are fixed as for a
-- close, but claims dated inside it can still be added, edited, opened, settled and voided. A soft-closed period is
-- not closed; closing it fixes the figures afresh, reopening drops them.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- Whether a claim was added while the period its date falls in was soft-closed.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A sheet's settings, one value per key (clerk-limit: a two-decimal amount; null: no limit). A key with no row
-- has no value.
CREATE TABLE setting (
    sheet_id    VARCHAR(200) NOT NULL,
    setting_key VARCHAR(50)  NOT NULL,
    setting_value VARCHAR(50),
    PRIMARY KEY (sheet_id, setting_key)
);

-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE user_role (
    sheet_id  VARCHAR(200) NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
package net.officefloor.hq.app.setting;

import java.time.LocalDate;

/** A sheet's setting: its key, its value as text (null: blank) and the date it is in force from (null: undated —
 *  a policy date or period numbering from-date, or a value from before settings were dated). */
public record Setting(String sheetId, String key, String value, LocalDate from) {
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's rate for a grade: a percent with two decimals, in force from its from-date (null: from the beginning of time)
 *  through its to-date (null: no end). */
public record Rate(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A grade a person has from a date until their next one's; a null {@code from} applies from the beginning of time. */
public record PersonGrade(String grade, LocalDate from) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A hold on a person from a date until a date (both included); a null {@code to} is open-ended. */
public record PersonHold(LocalDate from, LocalDate to) {

    public boolean covers(LocalDate date) {
        return !date.isBefore(from) && (to == null || !date.isAfter(to));
    }
}

