      <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-period">{periodOf(periods.data, c.date)?.name ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="claim-edit"
        onClick={() => {
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          lock.reset();
          setEditRefused(null);
          // refused at once when the screen already knows the claim cannot be edited; else the server decides
          if (c.status !== 'DRAFT' || periodOf(periods.data, c.date)?.closed) {
            setEditRefused(DRAFT_ONLY);
            return;
          }
          if (viewer) {
            setEditRefused(VIEWER_REFUSED);
            return;
          }
          if (c.lockedBy && c.lockedBy !== user) {
            setEditRefused(LOCK_REFUSED);
            return;
          }
          lock.mutate();
        }}
        disabled={lock.isPending}
      >
        Edit
      </button>
      {editing && (
        <button type="button" data-testid="claim-cancel" onClick={onCancel}>
package net.officefloor.hq.app.claim;


/** Checks the claim's editor may be opened: only a DRAFT claim not dated inside a closed period can be edited. */
public class ApplyLock {
    public void apply(@Val Claim claim, PeriodRepository periods) throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimStatusException("Only a DRAFT claim can be edited");
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
    }
}
